def count_3_digit():
    count = 0
    for d1 in [1, 2, 8]:
        for d2 in [0, 1, 2, 8]:
            for d3 in [0, 1, 2, 8]:
                if (d1 + d2 + d3) % 3 == 0:
                    count += 1
    return count

print(count_3_digit())

